from pathlib import Path
from html import escape
b=Path(__file__).resolve().parent
URL='https://github505050.github.io/web-studio/'
label='<div class="demo-label">Independent, fictional portfolio demonstration · No real appointments, purchases or accounts · <a href="/web-studio/live-demos/">Back to demo library</a></div>'
def doc(title,klass,slug,body):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} — Fictional Landing Page Demo</title><meta name="description" content="Fictional interactive landing page design demo by Sukhjindra Web Studio."><link rel="canonical" href="{URL}demos/{slug}/"><meta name="theme-color" content="#0b1736"><link rel="icon" type="image/svg+xml" href="/web-studio/assets/favicon.svg"><link rel="stylesheet" href="/web-studio/assets/demo.css"></head><body class="{klass}">{label}{body}<script src="/web-studio/js/sample-pages.js" defer></script></body></html>'''
def nav(brand,sections,buttonLabel='#contact'):
 return '<div class="wrap"><nav class="dm-nav" aria-label="Demo navigation"><a class="dm-brand" href="#top">'+brand+'</a><button data-dm-menu class="dm-menu" type="button" aria-controls="sample-nav" aria-expanded="false">Menu</button><div class="dm-links" id="sample-nav" data-dm-links>'+''.join(f'<a href="#{anchor}">{name}</a>' for name,anchor in sections)+'<a class="dm-button" href="'+buttonLabel+'">Explore next</a></div></nav></div>'
consult=nav('northstar<span style="color:#809f81">.</span>', [('Expertise','expertise'),('Approach','approach'),('Connect','contact')])
consult+='''<main id="top"><section class="wrap hero"><div><div class="dm-eyebrow">CLARITY THROUGH BETTER STRATEGY</div><h1>Good ideas need a clear direction.</h1><p>We help thoughtful organizations simplify their plans and find the next right move. A fictional consulting brand, created to demonstrate responsive web design.</p><a href="#expertise" class="dm-button">Explore our expertise ↗</a></div><div class="visual" aria-label="Abstract geometric editorial artwork"><span>Thoughtful direction, tangible progress.</span></div></section><section class="services dm-section" id="expertise"><div class="wrap"><div class="dm-title"><div class="dm-eyebrow">OUR PRACTICE</div><h2>Perspective that helps teams move forward.</h2><p>Clear services, realistic site navigation and a design that works with simple content.</p></div><div class="dm-grid"><article class="dm-card"><div class="num">01 / STRATEGY</div><h3>Business positioning</h3><p>Understand your audience and clarify your purpose.</p></article><article class="dm-card"><div class="num">02 / EXPERIENCE</div><h3>Service design</h3><p>Create journeys that make complex ideas easier to use.</p></article><article class="dm-card"><div class="num">03 / MOMENTUM</div><h3>Practical roadmaps</h3><p>Turn decisions into focused steps a team can follow.</p></article></div></div></section><section class="dm-section" id="approach"><div class="wrap story"><div class="story-image" aria-label="Geometric arch illustration"></div><div><div class="dm-eyebrow">OUR APPROACH</div><h2>Start with the right question.</h2><p>Strong strategy begins with listening. We map a challenge, explore possible paths and make the next decision easy to understand.</p><p>Every element on this demonstration page uses original, simple frontend markup. These are fictional descriptions, not actual client credentials.</p><div class="dm-stats"><div><strong>Listen</strong><span>Understand the context</span></div><div><strong>Explore</strong><span>Consider the choices</span></div><div><strong>Clarify</strong><span>Find the next step</span></div></div></div></div></section><section class="dm-section contact" id="contact"><div class="wrap"><div class="dm-eyebrow">LET'S GET CLEAR</div><h2>Better direction starts with a conversation.</h2><p>This is a fictional sample business. To discuss the real developer's services, use the original Upwork profile.</p><a class="dm-button" href="https://www.upwork.com/freelancers/~01c8c9a3158757bd3b" target="_blank" rel="noopener noreferrer">Developer on Upwork ↗</a></div></section></main><footer class="dm-foot"><div class="wrap"><strong>northstar. — Fictional demonstration</strong><span>Responsive consulting landing page · Sukhjindra Web Studio</span></div></footer>'''
(b/'demos/consulting/index.html').write_text(doc('Northstar Consulting','consult','consulting',consult),encoding='utf8')

well=nav('solace <em>studio</em>',[('Philosophy','philosophy'),('Classes','classes'),('Our space','connect')],'#classes')
well+='''<main id="top"><section class="wrap hero"><div><div class="dm-eyebrow">MOVE • BREATHE • RECONNECT</div><h1>Make room for <em>yourself.</em></h1><p>A gentler pace, a brighter outlook. This fictional wellness studio brings a warm editorial feeling to a fully responsive landing page.</p><a class="dm-button" href="#classes">Explore the class schedule ↗</a></div><div class="visual" aria-label="Abstract organic wellness illustration"><span class="badge">A little space, just for you.</span></div></section><section class="dm-section values" id="philosophy"><div class="wrap"><div class="dm-title"><div class="dm-eyebrow">THE SOLACE WAY</div><h2>Small moments. Meaningful rituals.</h2><p>Three pathways for rest, movement and everyday balance—illustrative services for this design study.</p></div><div class="dm-grid"><article class="dm-card"><div class="shape"></div><h3>Find your rhythm</h3><p>Gentle movement to feel more connected with yourself.</p></article><article class="dm-card"><div class="shape"></div><h3>Slow down</h3><p>Breath-led pauses to break up a busy schedule.</p></article><article class="dm-card"><div class="shape"></div><h3>Make space</h3><p>A welcoming atmosphere for your own way of being.</p></article></div></div></section><section class="dm-section classes" id="classes"><div class="wrap"><div class="dm-title"><div class="dm-eyebrow">WEEKLY PRACTICE • SAMPLE TIMES</div><h2>Choose your moment.</h2><p>Change the category to switch between two real, functional example schedules. These are not bookable classes.</p></div><div class="dm-toggle" role="group" aria-label="Sample class category"><button data-class-type="movement" aria-pressed="true" type="button">Movement</button><button data-class-type="breath" aria-pressed="false" type="button">Breath & stillness</button></div><div class="class-list" data-schedule aria-live="polite"></div><p class="dm-notice" style="margin-top:22px">Illustrative classes and hours only. No appointments are taken on this demo page.</p></div></section><section class="dm-section cta" id="connect"><div class="wrap"><div class="dm-eyebrow">RETURN TO YOURSELF</div><h2>Thoughtful websites can feel like a place.</h2><p>Explore the developer's other working web examples. This business and schedule are fictional.</p><a class="dm-button" href="/web-studio/live-demos/">Back to live demos ↗</a></div></section></main><footer class="dm-foot"><div class="wrap"><strong>solace studio · fictional sample</strong><span>Wellness landing page · Sukhjindra Web Studio</span></div></footer>'''
(b/'demos/wellness/index.html').write_text(doc('Solace Studio Wellness','well','wellness',well),encoding='utf8')

saas=nav('OrbitFlow',[('Features','features'),('Calculator','calculator'),('About','about')],'#calculator')
saas+='''<main id="top"><section class="hero"><div class="wrap"><div class="dm-eyebrow">LESS ADMIN. MORE CREATIVE SPACE.</div><h1>Make room for <span>better work.</span></h1><p>A fictional product concept showing how clean dashboards and clear interactions can support a compelling SaaS landing page.</p><a class="dm-button" href="#calculator">Try the sample calculator ↗</a><div class="app-ui" role="img" aria-label="Illustrative fictional software dashboard preview"><div class="app-top"><b></b><b></b><b></b></div><div class="app-body"><div class="app-side"><i></i><i></i><i></i><i></i><i></i></div><div class="app-body-main"><div class="dm-chip" style="color:#cdd4ff;margin-bottom:20px">Workspace activity · Illustrative chart</div><div class="app-bars"><span></span><span></span><span></span><span></span><span></span><span></span></div></div></div></div></div></section><section class="dm-section features" id="features"><div class="wrap"><div class="dm-title"><div class="dm-eyebrow">DESIGNED FOR FOCUS</div><h2>One calm place for moving work forward.</h2><p style="color:#b9c2e2">Illustrative feature concepts, not claims of a connected SaaS product.</p></div><div class="dm-grid"><article class="dm-card"><div class="symbol">◈</div><h3>Organize the work</h3><p>Visual structures that help people understand priorities at a glance.</p></article><article class="dm-card"><div class="symbol">◎</div><h3>Reduce the noise</h3><p>Less clutter, more room for the details that deserve attention.</p></article><article class="dm-card"><div class="symbol">✳</div><h3>Keep momentum</h3><p>Friendly feedback and thoughtfully designed interactive tools.</p></article></div></div></section><section class="dm-section calculator" id="calculator"><div class="wrap calc-layout"><div><div class="dm-eyebrow">INTERACTIVE PRODUCT CONCEPT</div><h2>What could a small time saving add up to?</h2><p>A simple local calculator demonstrating reactive JavaScript. The assumed 25% time saving is a user-interface illustration, not an evidence-based product outcome.</p><label for="hours"><strong>Hours of repetitive work per week: <output data-hours-val for="hours">10</output></strong></label><input type="range" min="1" max="40" step="1" value="10" id="hours" data-hours><p class="dm-notice">Formula: hours/week × 25% assumed savings × four weeks.</p></div><div class="calc-output"><div class="dm-eyebrow" style="color:#777eb5">ILLUSTRATIVE MONTHLY HOURS</div><strong data-savings aria-live="polite">10 h</strong><p>Example hours that could be saved under the stated assumption. No actual performance guarantee.</p><div style="height:12px;background:#e2e6fa;border-radius:20px;margin-top:26px"><div style="height:12px;width:25%;background:#686ee7;border-radius:20px"></div></div></div></div></section><section class="dm-section cta" id="about"><div class="wrap"><h2>Designed to explain what matters.</h2><p>OrbitFlow is a fictional interface demonstration, not a subscription product or active service.</p><a class="dm-button" href="/web-studio/live-demos/">Explore more working examples ↗</a></div></section></main><footer class="dm-foot"><div class="wrap"><strong>OrbitFlow — Fictional product concept</strong><span>Responsive SaaS landing page · Sukhjindra Web Studio</span></div></footer>'''
(b/'demos/saas/index.html').write_text(doc('OrbitFlow SaaS','saas','saas',saas),encoding='utf8')
print('3 demo pages generated')
